{
  "Role": "arn:aws:iam::111122223333:role/s3-crr-role",
  "Rules": [
    {
      "ID": "replicate-lake-to-dr",
      "Status": "Enabled",
      "Priority": 1,
      "Filter": { "Prefix": "curated/" },
      "DeleteMarkerReplication": { "Status": "Enabled" },
      "Destination": {
        "Bucket": "arn:aws:s3:::lake-dr-us-west-2",
        "StorageClass": "STANDARD_IA",
        "ReplicationTime": { "Status": "Enabled", "Time": { "Minutes": 15 } },
        "Metrics": { "Status": "Enabled", "EventThreshold": { "Minutes": 15 } },
        "EncryptionConfiguration": { "ReplicaKmsKeyID": "arn:aws:kms:us-west-2:111122223333:key/dr-key" }
      },
      "SourceSelectionCriteria": {
        "SseKmsEncryptedObjects": { "Status": "Enabled" }
      }
    }
  ]
}

// --- DynamoDB: add a us-west-2 replica to make an active-active global table ---
// aws dynamodb update-table --table-name orders --cli-input-json file://ddb-global.json
{
  "TableName": "orders",
  "ReplicaUpdates": [
    { "Create": { "RegionName": "us-west-2", "KMSMasterKeyId": "arn:aws:kms:us-west-2:111122223333:key/dr-key" } }
  ]
}
